  s8.addText("Source: Our World in Data — Mental Health | Data: IHME, Global Burden of Disease (2025) | Dattani, Rodés-Guirao, Ritchie & Roser (2023)", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.25,
    fontSize: 10, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  // Write file
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
