const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const {
  FaFemale, FaMale, FaBrain, FaPills, FaPray,
  FaUsers, FaBan, FaHospital, FaExclamationTriangle, FaEyeSlash
} = require("react-icons/fa");

function renderIconSvg(IconComponent, color, size) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

const makeShadow = (blur = 6, offset = 2, opacity = 0.12) => ({
  type: "outer", blur, offset, angle: 135, color: "000000", opacity
});
const makeShadowSm = () => makeShadow(4, 1, 0.08);

async function main() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data / IHME";
  pres.title = "The Global Burden of Mental Illness";

  const C = {
    dark: "1E3A5F", teal: "2A7B88", coral: "E07A5F", cream: "F7F3ED",
    white: "FFFFFF", charcoal: "2D3748", slate: "64748B",
    paleTeal: "D4E8E0", paleCoral: "FCEAE5", cardDark: "243B5E",
    lightText: "E2E8F0", midText: "CBD5E1",
    iconBg1: "D4E8E0", iconBg2: "FCEAE5", iconBg3: "E8F0FE",
  };

  // Generate icons
  const icons = {};
  const iconDefs = [
    ["female", FaFemale, "#FFFFFF"], ["male", FaMale, "#FFFFFF"],
    ["brain", FaBrain, "#FFFFFF"], ["pills", FaPills, "#2A7B88"],
    ["pray", FaPray, "#2A7B88"], ["users", FaUsers, "#2A7B88"],
    ["ban", FaBan, "#E07A5F"], ["hospital", FaHospital, "#E07A5F"],
    ["exclamation", FaExclamationTriangle, "#E07A5F"],
    ["eyeSlash", FaEyeSlash, "#E07A5F"],
  ];
  for (const [name, comp, color] of iconDefs) {
    icons[name] = await iconToBase64Png(comp, color, 256);
  }

  // ==================== SLIDE 1: TITLE ====================
  let s1 = pres.addSlide();
  s1.background = { color: C.dark };

  s1.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625,
    fill: { color: C.coral }
  });

  s1.addText("The Global Burden of\nMental Illness", {
    x: 0.8, y: 1.3, w: 7.2, h: 1.6,
    fontSize: 40, fontFace: "Georgia",
    color: C.white, bold: true, align: "left", valign: "middle", margin: 0
  });

  s1.addText("Prevalence, Impact, and the Treatment Gap", {
    x: 0.8, y: 3.0, w: 8, h: 0.5,
    fontSize: 20, fontFace: "Calibri",
    color: C.paleTeal, align: "left", margin: 0
  });

  s1.addImage({ data: icons.brain, x: 8.2, y: 1.3, w: 1.0, h: 1.0 });

  s1.addText("Global data, 2023  |  Our World in Data  |  IHME, Global Burden of Disease", {
    x: 0.8, y: 4.85, w: 8, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  // ==================== SLIDE 2: PREVALENCE ====================
  let s2 = pres.addSlide();
  s2.background = { color: C.cream };

  s2.addText("Hundreds of Millions Affected", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.5,
    fontSize: 30, fontFace: "Georgia",
    color: C.charcoal, bold: true, align: "left", margin: 0
  });

  s2.addText("1 in 3 women and 1 in 5 men will face major depression in their lifetime", {
    x: 0.6, y: 0.8, w: 8.8, h: 0.3,
    fontSize: 14, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  // Women card
  s2.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.3, w: 4.1, h: 2.6,
    fill: { color: C.teal }, shadow: makeShadow()
  });
  s2.addImage({ data: icons.female, x: 1.1, y: 1.55, w: 0.5, h: 0.5 });
  s2.addText("Women", {
    x: 1.7, y: 1.55, w: 2.5, h: 0.5,
    fontSize: 15, fontFace: "Calibri",
    color: C.paleTeal, bold: true, align: "left", valign: "middle", margin: 0
  });
  s2.addText("1 in 3", {
    x: 0.6, y: 2.1, w: 4.1, h: 0.9,
    fontSize: 56, fontFace: "Georgia",
    color: C.white, bold: true, align: "center", margin: 0
  });
  s2.addText("will experience major depression", {
    x: 0.6, y: 3.0, w: 4.1, h: 0.45,
    fontSize: 13, fontFace: "Calibri",
    color: C.paleTeal, align: "center", margin: 0
  });

  // Men card
  s2.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.3, w: 4.1, h: 2.6,
    fill: { color: C.coral }, shadow: makeShadow()
  });
  s2.addImage({ data: icons.male, x: 5.8, y: 1.55, w: 0.5, h: 0.5 });
  s2.addText("Men", {
    x: 6.4, y: 1.55, w: 2.5, h: 0.5,
    fontSize: 15, fontFace: "Calibri",
    color: C.paleCoral, bold: true, align: "left", valign: "middle", margin: 0
  });
  s2.addText("1 in 5", {
    x: 5.3, y: 2.1, w: 4.1, h: 0.9,
    fontSize: 56, fontFace: "Georgia",
    color: C.white, bold: true, align: "center", margin: 0
  });
  s2.addText("will experience major depression", {
    x: 5.3, y: 3.0, w: 4.1, h: 0.45,
    fontSize: 13, fontFace: "Calibri",
    color: C.paleCoral, align: "center", margin: 0
  });

  s2.addText("Mental health conditions span from common (depression, anxiety) to less common but severe (schizophrenia, bipolar disorder). Understanding prevalence is essential for effective policy.", {
    x: 0.6, y: 4.2, w: 8.8, h: 0.65,
    fontSize: 13, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  // ==================== SLIDE 3: BURDEN BY CATEGORY ====================
  let s3 = pres.addSlide();
  s3.background = { color: C.cream };

  s3.addText("Depression and Anxiety Dominate", {
    x: 0.6, y: 0.3, w: 9, h: 0.5,
    fontSize: 30, fontFace: "Georgia",
    color: C.charcoal, bold: true, align: "left", margin: 0
  });

  s3.addText("DALYs per 100,000 people by mental illness category, World, 2023", {
    x: 0.6, y: 0.78, w: 9, h: 0.3,
    fontSize: 13, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  s3.addChart(pres.charts.BAR, [{
    name: "DALYs per 100K",
    labels: ["Depressive disorders", "Anxiety disorders", "Schizophrenia", "Bipolar disorder", "Eating disorders"],
    values: [694.6, 686.5, 210.2, 94.6, 47.5]
  }], {
    x: 0.5, y: 1.15, w: 8.8, h: 3.8,
    barDir: "bar",
    chartColors: ["2A7B88"],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    catAxisLabelColor: C.charcoal,
    catAxisLabelFontSize: 12,
    valAxisLabelColor: C.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.charcoal,
    dataLabelFontSize: 12,
    showLegend: false,
    showTitle: false,
    valAxisHidden: true,
  });

  s3.addText("Source: IHME, Global Burden of Disease (2025) via Our World in Data", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.25,
    fontSize: 10, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  // ==================== SLIDE 4: DEPRESSION VS ANXIETY PARITY ====================
  let s4 = pres.addSlide();
  s4.background = { color: C.cream };

  s4.addText("Depression and Anxiety Carry\nNearly Equal Disease Burden", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.9,
    fontSize: 26, fontFace: "Georgia",
    color: C.charcoal, bold: true, align: "left", margin: 0
  });

  // Depression card
  s4.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.4, w: 4.1, h: 2.8,
    fill: { color: C.white }, shadow: makeShadowSm()
  });
  s4.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.4, w: 4.1, h: 0.07,
    fill: { color: C.teal }
  });
  s4.addText("Depressive\nDisorders", {
    x: 0.6, y: 1.6, w: 4.1, h: 0.6,
    fontSize: 16, fontFace: "Calibri",
    color: C.slate, bold: true, align: "center", margin: 0
  });
  s4.addText("694.6", {
    x: 0.6, y: 2.25, w: 4.1, h: 1.1,
    fontSize: 52, fontFace: "Georgia",
    color: C.teal, bold: true, align: "center", margin: 0
  });
  s4.addText("DALYs per 100,000", {
    x: 0.6, y: 3.4, w: 4.1, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: C.slate, align: "center", margin: 0
  });

  // Anxiety card
  s4.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.4, w: 4.1, h: 2.8,
    fill: { color: C.white }, shadow: makeShadowSm()
  });
  s4.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.4, w: 4.1, h: 0.07,
    fill: { color: C.coral }
  });
  s4.addText("Anxiety\nDisorders", {
    x: 5.3, y: 1.6, w: 4.1, h: 0.6,
    fontSize: 16, fontFace: "Calibri",
    color: C.slate, bold: true, align: "center", margin: 0
  });
  s4.addText("686.5", {
    x: 5.3, y: 2.25, w: 4.1, h: 1.1,
    fontSize: 52, fontFace: "Georgia",
    color: C.coral, bold: true, align: "center", margin: 0
  });
  s4.addText("DALYs per 100,000", {
    x: 5.3, y: 3.4, w: 4.1, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: C.slate, align: "center", margin: 0
  });

  s4.addText("Together, depression and anxiety account for roughly 80% of the total mental health disease burden across these five categories, dwarfing all other conditions.", {
    x: 0.6, y: 4.5, w: 8.8, h: 0.55,
    fontSize: 13, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  // ==================== SLIDE 5: SEVERE CONDITIONS ====================
  let s5 = pres.addSlide();
  s5.background = { color: C.cream };

  s5.addText("Lower Prevalence but Severe\nIndividual Impact", {
    x: 0.6, y: 0.3, w: 9, h: 0.9,
