  });

  const maxDALY = 694.6;
  const barMaxW = 5.3;
  const barStartX = 3.2;
  const labelW = 2.4;

  function addBurdenBar(slide, label, value, yPos, barColor, isHighlight) {
    slide.addText(label, {
      x: 0.6, y: yPos, w: labelW, h: 0.38,
      fontSize: 12, fontFace: "Calibri",
      color: isHighlight ? C.charcoal : C.slate,
      bold: isHighlight, align: "right", valign: "middle", margin: 0
    });
    const barW = barMaxW * (value / maxDALY);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: barStartX, y: yPos, w: barW, h: 0.38,
      fill: { color: barColor, transparency: isHighlight ? 0 : 35 }
    });
    slide.addText(String(value), {
      x: barStartX + barW + 0.1, y: yPos, w: 1.0, h: 0.38,
      fontSize: 11, fontFace: "Calibri",
      color: isHighlight ? C.coral : C.slate,
      bold: true, align: "left", valign: "middle", margin: 0
    });
  }

  addBurdenBar(s5, "Depressive disorders", 694.6, 1.5, C.teal, false);
  addBurdenBar(s5, "Anxiety disorders", 686.5, 2.0, C.teal, false);
  addBurdenBar(s5, "Schizophrenia", 210.2, 2.5, C.coral, true);
  addBurdenBar(s5, "Bipolar disorder", 94.6, 3.0, C.coral, true);
