      fontSize: 16, fontFace: "Calibri",
      color: C.coral, bold: true, valign: "middle", margin: 0
    });
    s6.addText(card.desc, {
      x: cx + 0.2, y: cy + 0.65, w: cardW - 0.4, h: 0.6,
