    fontSize: 30, fontFace: "Georgia",
    color: C.charcoal, bold: true, align: "left", margin: 0
  });

  s7.addText("From medication to faith to family conversations — coping strategies vary widely across countries", {
    x: 0.6, y: 0.78, w: 8.8, h: 0.3,
    fontSize: 13, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  const colW = 2.7;
  const colGap = 0.45;
  const csx = 0.75;
  const csy = 1.3;
  const colH = 3.1;

  const copingCols = [
    { icon: "pills", bg: C.iconBg1, title: "Prescribed\nMedication", desc: "Common in higher-income settings where healthcare infrastructure and access to pharmaceuticals are more available" },
    { icon: "pray", bg: C.iconBg2, title: "Religious &\nSpiritual Activities", desc: "Prevalent in many regions worldwide, reflecting deep cultural and spiritual traditions in mental health" },
    { icon: "users", bg: C.iconBg3, title: "Talking to\nFriends & Family", desc: "A widely reported coping mechanism across cultures and income levels" },
  ];

  copingCols.forEach((col, i) => {
    const cx = csx + i * (colW + colGap);

    s7.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: csy, w: colW, h: colH,
