    const iconSize = 0.42;
    s7.addImage({
      data: icons[col.icon],
      x: cx + (colW - iconSize) / 2, y: csy + 0.25 + (circSize - iconSize) / 2,
      w: iconSize, h: iconSize
    });

    s7.addText(col.title, {
      x: cx, y: csy + 1.1, w: colW, h: 0.6,
      fontSize: 14, fontFace: "Calibri",
      color: C.charcoal, bold: true, align: "center", margin: 0
    });

    s7.addText(col.desc, {
      x: cx + 0.2, y: csy + 1.75, w: colW - 0.4, h: 1.2,
      fontSize: 11.5, fontFace: "Calibri",
      color: C.slate, align: "center", margin: 0
    });
  });

  s7.addText("The diversity of coping strategies underscores that mental health responses are shaped by cultural, economic, and healthcare system factors. Policy interventions must account for these differences.", {
    x: 0.6, y: 4.6, w: 8.8, h: 0.5,
    fontSize: 12, fontFace: "Calibri",
    color: C.slate, italic: true, align: "left", margin: 0
  });

  // ==================== SLIDE 8: TAKEAWAYS ====================
  let s8 = pres.addSlide();
  s8.background = { color: C.dark };

  s8.addText("Key Takeaways", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.5,
    fontSize: 32, fontFace: "Georgia",
    color: C.white, bold: true, align: "left", margin: 0
  });

  s8.addText("Prioritizing Depression, Anxiety, and Closing the Treatment Gap", {
    x: 0.6, y: 0.78, w: 8.8, h: 0.3,
    fontSize: 15, fontFace: "Calibri",
    color: C.paleTeal, align: "left", margin: 0
  });

  const takeaways = [
    "Depression and anxiety together represent the overwhelming majority of mental health DALYs",
    "Schizophrenia and bipolar carry disproportionate individual burden relative to prevalence",
    "Treatment exists but access and quality remain inadequate",
    "Stigma suppresses both help-seeking and accurate data",
    "Policy should prioritize scaling evidence-based interventions for common mental disorders while maintaining specialized care for severe conditions",
  ];

  const tkStartY = 1.3;
  const tkItemH = 0.62;
  const tkGap = 0.1;

  takeaways.forEach((text, i) => {
    const y = tkStartY + i * (tkItemH + tkGap);
    const num = String(i + 1).padStart(2, "0");

    s8.addText(num, {
      x: 0.6, y: y, w: 0.55, h: 0.4,
      fontSize: 20, fontFace: "Georgia",
      color: C.coral, bold: true, align: "center", valign: "top", margin: 0
    });

    // Short accent bar instead of full-height separator
    s8.addShape(pres.shapes.RECTANGLE, {
      x: 1.25, y: y + 0.05, w: 0.04, h: 0.3,
      fill: { color: C.teal }
    });

    s8.addText(text, {
      x: 1.5, y: y, w: 8.0, h: tkItemH,
      fontSize: 13.5, fontFace: "Calibri",
      color: C.lightText, align: "left", valign: "top", margin: 0
    });
  });

  s8.addText("Source: Our World in Data — Mental Health | Data: IHME, Global Burden of Disease (2025) | Dattani, Rodés-Guirao, Ritchie & Roser (2023)", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.25,
    fontSize: 10, fontFace: "Calibri",
    color: C.slate, align: "left", margin: 0
  });

  // Write file
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Done: /app/output/final_deck.pptx");
}

main().catch(err => { console.error(err); process.exit(1); });

